#!/usr/bin/env python3
"""Check production locale positions and stage generated bytes, never ROM data.

Run after bootstrap: python3 3ds_port/tests/randomizer_locale_test.py --tree .
The fixture records positions and hashes, not the source strings or ROM payload.
"""
import argparse
import contextlib
import gzip
import hashlib
import importlib
import io
import json
from pathlib import Path
import struct
import sys
import tempfile
import unittest
from unittest.mock import patch

ROOT = Path(__file__).resolve().parents[2]
TREE = ROOT
sys.path.insert(0, str(ROOT / "tools"))
sys.path.insert(0, str(ROOT / "builder"))
from emerald3ds_builder.rom import Rom


def digest(data):
    return hashlib.sha256(data).hexdigest()


def already_localized(tree):
    marker = tree / ".emerald3ds-locale"
    if not marker.is_file():
        return False
    return marker.read_text(encoding="utf-8").strip() in {
        "BPES experimental", "BPEF experimental", "BPEI experimental", "BPED experimental",
    }


class LocaleTreeSelectionTests(unittest.TestCase):
    def test_only_production_localization_markers_select_skip(self):
        with tempfile.TemporaryDirectory() as temporary:
            tree = Path(temporary)
            marker = tree / ".emerald3ds-locale"
            self.assertFalse(already_localized(tree))
            for value in ("BPES experimental", "BPEF experimental", "BPEI experimental", "BPED experimental"):
                with self.subTest(marker=value):
                    marker.write_text(value + "\n")
                    self.assertTrue(already_localized(tree))
            for value in ("", "BPEE experimental", "BPES", "unrecognized"):
                with self.subTest(marker=value):
                    marker.write_text(value + "\n")
                    self.assertFalse(already_localized(tree))


class RandomizerLocaleTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        if already_localized(TREE):
            raise unittest.SkipTest(
                "already-localized tree: source-hash/stager checks require the "
                "English bootstrap tree before localization")

    def test_full_patched_source_hashes_and_edit_bounds(self):
        for language in ("spanish", "french", "italian", "german"):
            manifest = self.manifest(language)
            for relative, file in manifest["files"].items():
                with self.subTest(language=language, file=relative):
                    text = (TREE / relative).read_text(encoding="utf-8")
                    self.assertEqual(digest(text.encode()), file["sha256"])
                    previous_end = 0
                    for start, end, *_ in sorted(file["edits"]):
                        self.assertTrue(previous_end <= start < end <= len(text))
                        previous_end = end

    @staticmethod
    def manifest(language):
        path = ROOT / "tools/locales" / (language + ".json.gz")
        return json.loads(gzip.decompress(path.read_bytes()))

    def test_text_targets_and_rom_references_are_preserved(self):
        fixture = json.loads((ROOT / "3ds_port/tests/randomizer_locale_targets.json").read_text())
        text = (TREE / "src/battle_main.c").read_text(encoding="utf-8")
        for language in ("spanish", "french", "italian"):
            edits = self.manifest(language)["files"]["src/battle_main.c"]["edits"]
            self.assertEqual(len(edits), len(fixture["targets"]))
            self.assertEqual(digest(json.dumps([e[2:] for e in edits]).encode()),
                             fixture["rom_references_sha256"][language])
            for edit, (old_start, old_end, expected_hash) in zip(edits, fixture["targets"]):
                with self.subTest(language=language, baseline_start=old_start):
                    start, end = edit[:2]
                    self.assertEqual(end - start, old_end - old_start)
                    self.assertEqual(digest(text[start:end].encode()), expected_hash)

    def test_all_three_real_stagers_accept_source_and_reject_tampering(self):
        original = (TREE / "src/battle_main.c").read_bytes()
        for language, code in (("spanish", "BPES"), ("french", "BPEF"), ("italian", "BPEI")):
            module = importlib.import_module("localize_" + language)
            manifest = self.manifest(language)
            entry = manifest["files"]["src/battle_main.c"]
            # Keep the actual production entry/hash/ROM positions. Other assets
            # are outside this patch; their source hashes are checked above.
            reduced = {"rom_sha1": manifest["rom_sha1"],
                       "files": {"src/battle_main.c": entry}, "graphics": [],
                       "credits": 0, "credits_entries": 275, "floors": []}
            size = max(e[2] + e[3] for e in entry["edits"])
            data = bytearray(size)
            for index, (_, _, offset, length, _) in enumerate(entry["edits"]):
                data[offset:offset + length] = bytes((index + n) % 256 for n in range(length))
            # Generated, valid credits pointers; Spanish always reads 275.
            for index in range(275):
                struct.pack_into("<I", data, index * 4, 0x08000800)
            struct.pack_into("<BBHI", data, 2048, 0, 0, 0, 0x08000810)
            data[2064] = 0xff
            with tempfile.TemporaryDirectory() as temporary:
                root = Path(temporary)
                tree = root / "tree"
                path = tree / "src/battle_main.c"
                path.parent.mkdir(parents=True)
                for relative, content in {
                    "src/data/credits.h": "/* generated test placeholder */\n",
                    "src/data/battle_frontier/trainer_hill.h": "/* no floors */\n",
                    "include/constants/global.h": "#define GAME_LANGUAGE (LANGUAGE_ENGLISH)\n",
                }.items():
                    target = tree / relative
                    target.parent.mkdir(parents=True, exist_ok=True)
                    target.write_text(content)
                locales = root / "tools/locales"
                locales.mkdir(parents=True)
                (locales / (language + ".json.gz")).write_bytes(gzip.compress(json.dumps(reduced).encode()))
                (locales / (language + "-symbols.s.gz")).write_bytes(gzip.compress(b".syntax unified\n"))
                # Replace only the ROM loader with a synthetic in-memory result.
                # The production source-hash guard and staging code run intact.
                rom = Rom(bytes(data), manifest["rom_sha1"], "SYNTHETIC", code, root / "unused")
                with patch.object(module, "ROOT", root), \
                        patch.object(module, "load_rom", return_value=rom), \
                        contextlib.redirect_stdout(io.StringIO()):
                    with self.subTest(language=language, case="tampered"):
                        path.write_bytes(original + b"\n/* unexpected edit */\n")
                        before = path.read_bytes()
                        with self.assertRaisesRegex(ValueError, "Source differs"):
                            module.stage(tree, rom.source)
                        self.assertEqual(path.read_bytes(), before)
                        self.assertFalse((tree / ".emerald3ds-locale").exists())
                    with self.subTest(language=language, case="valid"):
                        path.write_bytes(original)
                        expected = original.decode()
                        for start, end, offset, length, kind in sorted(entry["edits"], reverse=True):
                            self.assertEqual(kind, "c")
                            replacement = "{" + module.encoded(data[offset:offset + length]) + "}"
                            expected = expected[:start] + replacement + expected[end:]
                        module.stage(tree, rom.source)
                        self.assertEqual(path.read_text(), expected)
                        self.assertTrue((tree / ".emerald3ds-locale").exists())
                        self.assertIn("TRAINER_MON_SPECIES", path.read_text())


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--tree", type=Path, required=True, help="complete bootstrap-patched English tree")
    arguments, remainder = parser.parse_known_args()
    TREE = arguments.tree.resolve()
    unittest.main(argv=[sys.argv[0]] + remainder)
